function generate(rand, size) {
  const small = size === 'small';
  const busCount = small ? Math.floor(rand() * 5) : 300;
  const passengerCount = small ? Math.floor(rand() * 9) : 2000;
  const span = small ? 10 : 20000;
  // Distinct bus times; bus ids are shuffled so id order and time order differ.
  const times = new Set();
  while (times.size < busCount) times.add(1 + Math.floor(rand() * span));
  const ids = Array.from({ length: busCount }, (_, i) => i + 1);
  for (let i = ids.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [ids[i], ids[j]] = [ids[j], ids[i]]; }
  const Buses = [...times].map((time, i) => [ids[i], time]);
  const Passengers = [];
  for (let i = 0; i < passengerCount; i++) Passengers.push([small ? 11 + i : i + 1, 1 + Math.floor(rand() * (span + 1))]);
  return [{ Buses, Passengers }];
}
